import * as THREE from 'three/webgpu';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

interface NodeConfig {
  id: string;
  type: string;
  scenePosition?: {
    x?: number;
    y?: number;
    z?: number;
    rotationXYZ?: [number, number, number];
    scaleXYZ?: [number, number, number];
  };
  renderMode: string;
  textContent?: Record<string, string>;
  cinematicPrimitives?: Array<{ name: string; params: any }>;
  [key: string]: any;
}

interface NodeContext {
  textureLoader?: THREE.TextureLoader;
  glbLoader?: any;
  fontAtlas: any;
  primitives: Record<string, (target: THREE.Object3D, params: any) => void>;
}

export default function createNode(config: NodeConfig, ctx: NodeContext): THREE.Object3D {
  const root = new THREE.Group();

  // Design tokens
  const colors = {
    surface: 0x14141a,
    accent: 0xff2a38,
  };

  // Layout dimensions (scene units)
  const DOM = { w: 3.25, h: 3.5 };
  const SEC = { w: 2.0, h: 1.625 };
  const GUTTER = 0.25;
  const DEPTH = 0.06;
  const PAD = 0.5;

  // Grid geometry
  const GRID_W = 5.5;
  const GRID_H = 3.5;
  const LEFT = -GRID_W / 2;
  const TOP = GRID_H / 2;

  // Cell positions
  const dom_x = LEFT + DOM.w / 2;
  const dom_y = 0;
  const sec_col_x = LEFT + DOM.w + GUTTER + SEC.w / 2;
  const sec_top_y = TOP - SEC.h / 2;
  const sec_bot_y = sec_top_y - (SEC.h + GUTTER);

  // Material factory: machined-metal PBR
  function mkCellMat() {
    return new MeshStandardNodeMaterial({
      color: new THREE.Color(colors.surface),
      metalness: 0.45,
      roughness: 0.5,
      clearcoat: 0.2,
      side: THREE.FrontSide,
      wireframe: false,
    });
  }

  function mkTickMat() {
    return new MeshStandardNodeMaterial({
      color: new THREE.Color(colors.accent),
      emissive: new THREE.Color(colors.accent),
      emissiveIntensity: 1.3,
      metalness: 0,
      roughness: 0.3,
    });
  }

  // Create cell mesh
  function mkCell(w: number, h: number) {
    const g = new THREE.BoxGeometry(w, h, DEPTH);
    const m = mkCellMat();
    const mesh = new THREE.Mesh(g, m);
    return mesh;
  }

  // Create cells
  const cells = [];

  const dom = mkCell(DOM.w, DOM.h);
  dom.position.set(dom_x, dom_y, 0);
  root.add(dom);
  cells.push(dom);

  const sec1 = mkCell(SEC.w, SEC.h);
  sec1.position.set(sec_col_x, sec_top_y, 0);
  root.add(sec1);
  cells.push(sec1);

  const sec2 = mkCell(SEC.w, SEC.h);
  sec2.position.set(sec_col_x, sec_bot_y, 0);
  root.add(sec2);
  cells.push(sec2);

  // Add accent tick bars (top-left, inside padding)
  function addTick(parent: THREE.Mesh, cw: number, ch: number) {
    const tg = new THREE.BoxGeometry(0.4, 0.05, DEPTH * 2);
    const tm = mkTickMat();
    const t = new THREE.Mesh(tg, tm);
    t.position.set(-cw / 2 + PAD + 0.2, ch / 2 - PAD - 0.025, DEPTH * 0.6);
    parent.add(t);
  }

  addTick(dom, DOM.w, DOM.h);
  addTick(sec1, SEC.w, SEC.h);
  addTick(sec2, SEC.w, SEC.h);

  // Text rendering via MSDF
  const textMeshes = [];

  if (ctx.fontAtlas?.createTextMesh) {
    const content = [
      {
        text: 'ATELIER METRICS / Q2 2026',
        fontSize: 18,
        fontWeight: 700,
        family: 'JetBrains Mono',
        x: LEFT,
        y: TOP + 0.5,
      },
      {
        text: '0.002 mm',
        fontSize: 124,
        fontWeight: 600,
        family: 'Lora',
        x: dom_x - DOM.w / 2 + PAD + 0.25,
        y: dom_y + 0.3,
      },
      {
        text: 'Case tolerance, CNC pass',
        fontSize: 18,
        fontWeight: 400,
        family: 'JetBrains Mono',
        x: dom_x - DOM.w / 2 + PAD + 0.25,
        y: dom_y - 0.2,
      },
      {
        text: '38 h',
        fontSize: 68,
        fontWeight: 600,
        family: 'Lora',
        x: sec_col_x - SEC.w / 2 + PAD,
        y: sec_top_y + 0.1,
      },
      {
        text: 'Power reserve, NA-01',
        fontSize: 18,
        fontWeight: 400,
        family: 'JetBrains Mono',
        x: sec_col_x - SEC.w / 2 + PAD,
        y: sec_top_y - 0.4,
      },
      {
        text: '214',
        fontSize: 68,
        fontWeight: 600,
        family: 'Lora',
        x: sec_col_x - SEC.w / 2 + PAD,
        y: sec_bot_y + 0.1,
      },
      {
        text: 'Components per calibre',
        fontSize: 18,
        fontWeight: 400,
        family: 'JetBrains Mono',
        x: sec_col_x - SEC.w / 2 + PAD,
        y: sec_bot_y - 0.4,
      },
    ];

    content.forEach((spec) => {
      try {
        const mesh = ctx.fontAtlas.createTextMesh(spec.text, {
          fontSize: spec.fontSize,
          fontWeight: spec.fontWeight,
          family: spec.family,
          color: 0xe8ecf2,
        });
        if (mesh) {
          mesh.position.set(spec.x, spec.y, 0.1);
          root.add(mesh);
          textMeshes.push(mesh);
        }
      } catch (e) {
        console.warn(`Text render failed for "${spec.text}":`, e);
      }
    });
  }

  // Animation timeline
  const tl = gsap.timeline({ paused: false });

  // Initial state: offset and transparent
  const allMeshes = [...cells, ...textMeshes];
  allMeshes.forEach((mesh) => {
    gsap.set(mesh, { opacity: 0, y: mesh.position.y + 0.2 });
  });

  // Stagger entrance: fade-up, 80ms stagger, dominant cell first
  allMeshes.forEach((mesh, idx) => {
    const delay = idx * 0.08;
    tl.to(
      mesh,
      {
        opacity: 1,
        y: mesh.position.y,
        duration: 0.5,
        ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
      },
      delay
    );
  });

  // Hover interactions: press-down on over, weighted-settle on out
  cells.forEach((mesh) => {
    mesh.userData.handlers = {
      onPointerOver: () => {
        gsap.to(
          mesh.scale,
          {
            x: 0.97,
            y: 0.97,
            z: 0.97,
            duration: 0.12,
            ease: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)',
            overwrite: 'auto',
          }
        );
      },
      onPointerOut: () => {
        gsap.to(
          mesh.scale,
          {
            x: 1.04,
            y: 1.04,
            z: 1.04,
            duration: 0.05,
            ease: 'power2.out',
            overwrite: 'auto',
          }
        );
        gsap.to(
          mesh.scale,
          {
            x: 1,
            y: 1,
            z: 1,
            duration: 0.9,
            delay: 0.05,
            ease: 'cubic-bezier(0.165, 0.84, 0.44, 1)',
            overwrite: 'auto',
          }
        );
      },
    };
  });

  // Apply scenePosition
  if (config.scenePosition) {
    const { x = 0, y = 0, z = 0, rotationXYZ, scaleXYZ } = config.scenePosition;
    root.position.set(x, y, z);
    if (rotationXYZ) root.rotation.set(rotationXYZ[0], rotationXYZ[1], rotationXYZ[2]);
    if (scaleXYZ) root.scale.set(scaleXYZ[0], scaleXYZ[1], scaleXYZ[2]);
  }

  // Cleanup
  root.userData.cleanup = () => {
    tl.kill();
    root.traverse((obj: any) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m: any) => m.dispose?.());
        } else {
          obj.material.dispose?.();
        }
      }
    });
  };

  return root;
}
